    http_.route("/api/v1/focusers/<arg>/status",QHttpServerRequest::Method::Get,[this](QString){FocuserStatus s;QString e;if(!controller_->focuserStatus(s,&e))return fail("FOCUSER_STATUS_FAILED",e,Status::ServiceUnavailable);QJsonObject d{{"position",s.position},{"moving",s.moving}};if(s.temperatureC)d["temperatureC"]=*s.temperatureC;return ok(d);});
    http_.route("/api/v1/focusers/<arg>/move",QHttpServerRequest::Method::Post,[this](QString,const QHttpServerRequest&r){auto b=body(r);QString e;if(!controller_->moveFocuser(b.value("position").toInt(),&e))return deviceFailure("FOCUSER_MOVE_FAILED",e);return ok();});
    http_.route("/api/v1/focusers/<arg>/move-relative",QHttpServerRequest::Method::Post,[this](QString,const QHttpServerRequest&r){FocuserStatus s;QString e;if(!controller_->focuserStatus(s,&e))return fail("FOCUSER_STATUS_FAILED",e,Status::ServiceUnavailable);auto b=body(r);if(!controller_->moveFocuser(s.position+b.value("delta").toInt(),&e))return deviceFailure("FOCUSER_MOVE_FAILED",e);return ok();});
